<?php $pageTitle='Stock Management';require '../includes/admin-header.php';$q=db()->query('SELECT p.name,p.status,ps.size,ps.stock_quantity,COALESCE((SELECT SUM(oi.quantity) FROM order_items oi WHERE oi.product_id=p.id AND oi.size=ps.size),0) sold FROM product_sizes ps JOIN products p ON p.id=ps.product_id ORDER BY ps.stock_quantity,p.name');$rows=$q->fetchAll(); ?><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Product</th><th>Size</th><th>Current stock</th><th>Sold quantity</th><th>Remaining stock</th><th>Stock status</th></tr></thead><tbody><?php foreach($rows as $r): $status=$r['stock_quantity']==0?'Out of Stock':($r['stock_quantity']<=8?'Low Stock':'In Stock'); ?><tr><td><?=e($r['name'])?></td><td><?=$r['size']?></td><td><?=$r['stock_quantity']?></td><td><?=$r['sold']?></td><td><?=$r['stock_quantity']?></td><td><span class="badge <?=$status==='In Stock'?'text-bg-success':($status==='Low Stock'?'text-bg-warning':'text-bg-danger')?>"><?=$status?></span></td></tr><?php endforeach ?></tbody></table></div><?php require '../includes/admin-footer.php'; ?>
